from base_sensor import BaseVirtualSensor

class TMP461_Simulator(BaseVirtualSensor):
    REG_WIDTH = 16

    def __init__(self):
        super().__init__()
        for reg in self.device['registers']:
            self.regs[reg['addr']] = reg['reset']

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            raise KeyError(f"Register {addr:x} does not exist.")

        value = self.regs[addr]
        if nbytes == 1:
            return value >> 8  # Read high byte of 16-bit register

        return value

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            raise KeyError(f"Register {addr:x} does not exist.")

        if nbytes == 1:
            # Only update bits 15:8 for single-byte accesses
            self.regs[addr] &= 0xFF
            self.regs[addr] |= (data << 8)
        else:
            # Update entire register
            self.regs[addr] = data
